  // through at the peak so it reads as dense fog, not a blank frame; storm cells stay grey, not white).
  if (imm > 0.01) {
    ctx.fillStyle = rgb(mix(lit, [255, 255, 255], storm > 0.2 ? 0 : 0.16), imm * (storm > 0.2 ? 0.9 : 0.94));
    ctx.fillRect(0, 0, W, H);
  }
