      const al = fade * (0.65 + rnd(i + 3) * 0.35);
      const sg = ctx.createRadialGradient(sx, sy, 0, sx, sy, sparkR * 2);
      sg.addColorStop(0, `rgba(255,250,235,${al})`);
      sg.addColorStop(0.5, `rgba(${r},${g},${bl},${al * 0.8})`);
      sg.addColorStop(1, `rgba(${r},${g},${bl},0)`);
