    // TLOF aiming circle + the inner touchdown circle.
    ctx.strokeStyle = `rgba(${paint},${night ? 0.95 : 0.85})`; ctx.lineWidth = 2.2; trace(ring(r * 0.82));
    ctx.lineWidth = 1.2; ctx.strokeStyle = `rgba(${paint},0.55)`; trace(ring(r * 0.62));
