      { const [bx, by] = F(0, fh * 1.06); draw3DBoxAt(ctx, cam, bx, by, fh * 0.78, 0, h * 0.12, 'ty_trm_dorm_roof', seed + 14, night, alpha, true); }
      // 4) A single stove flue at the middle of the ridge. One fire for the whole hall.
