      draw3DBoxAt(ctx, cam, dx, dy, fh * 0.98, 0, wallTop, pal, seed, night, alpha, false);
      draw3DBoxAt(ctx, cam, dx, dy, fh * 1.08, wallTop, roof, 'ty_trm_frame', seed + 1, night, alpha, true);
