      const wallTop = h * 0.80, ridge = h * 0.96;
      draw3DBoxAt(ctx, cam, dx, dy, fh * 1.02, 0, wallTop, pal, seed, night, alpha, false);
      draw3DBoxAt(ctx, cam, dx, dy, fh * 1.10, wallTop, ridge, 'ty_trm_frame', seed + 1, night, alpha, true);
