      const wallTop = h * 0.62, roof = h * 0.70;
      draw3DBoxAt(ctx, cam, dx, dy, fh * 0.82, 0, wallTop, pal, seed, night, alpha, false);
      draw3DBoxAt(ctx, cam, dx, dy, fh * 0.92, wallTop, roof, pal, seed + 1, night, alpha, true);
