      awning(ctx, cam, dx, dy, E, fh * 0.78, fh * 0.92, h * 0.22, h * 0.34, 'ty_door', seed + 1, night, alpha, fh * 0.26);   // door awning
      { const [nx, ny] = F(fh * 0.5, fh * 0.4); neonBlade(ctx, cam, nx, ny, h * 0.34, h * 1.2, m.neon || '#5fd0ff', night, alpha); }
